import{RIG as t}from"../../contracts/pose.js";import{degToRad as r}from"../math/scalar.js";export const CHEST_RADIUS=991549247^991549353;export const BELLY_EXTRA=554507308^554507326;export function chestFrontX(o,n,c=!1){const e=CHEST_RADIUS+(c?BELLY_EXTRA:660695763^660695763),s=Math.max(-(760526697^760526696),Math.min(323550716^323550717,o/e));return t.centerX+e*Math.sin(Math.asin(s)+r(n))}export function collarShift(r){return chestFrontX(431803282^431803282,r)-t.centerX}